-- PT119-S2-Q5. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT119-S2-Q5$batch10$ AND q.stimulus=$batch10$Futurist: Artists in the next century will be supported largely by private patrons. Because these patrons will almost invariably be supporters of the social order—whatever it happens to be at the time—art in the next century will rarely express social and political doctrines that are perceived to be subversive of that social order.$batch10$ AND q.prompt=$batch10$Which one of the following principles, if valid, provides the most support for the futurist's inference?$batch10$ AND q.correct_choice=$batch10$A$batch10$) THEN RAISE EXCEPTION 'Question changed: PT119-S2-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT119-S2-Q5$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT119-S2-Q5'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT119-S2-Q5$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$Art in the next century will rarely express views seen as subversive of the social order.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$Artists will be supported mostly by private patrons, and these patrons will almost always support the social order.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$The futurist jumps from what patrons believe to what art will say. The gap is that patrons won't fund art that opposes their views. The principle needs to supply that.$batch10$), (3, $batch10$Goal$batch10$, $batch10$Patrons tend not to support artists whose work opposes the patrons' views.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT119-S2-Q5$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$Patrons will support the social order, and this principle says they won't back art that opposes their views. So subversive art won't get funding, and it will rarely be made.$batch10$), ($batch10$B$batch10$, $batch10$If patrons don't care about social issues, their politics wouldn't shape what they fund. That weakens the futurist's link.$batch10$), ($batch10$C$batch10$, $batch10$If artists attack and defend the order equally, we'd expect plenty of subversive art unless something stops it. This gives no reason patrons would stop it.$batch10$), ($batch10$D$batch10$, $batch10$This is about artists freed from patrons. In the futurist's next century, artists depend on patrons.$batch10$), ($batch10$E$batch10$, $batch10$If patrons don't oppose change started by artists, they might fund subversive art. That cuts against the conclusion.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT119-S2-Q5$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
